    },
    {
      "Acronym": "PA",
      "Expansion": "Prior Authorization",
      "Explanation": "The process of obtaining approval for certain prescriptions before benefits will be approved. You, your doctor or other network provider will need to request prior authorization before you fill the prescription."
    },
    {
      "Acronym": "ST",
      "Expansion": "Step Therapy",
      "Explanation": "The process of first trying a certain drug or drugs to determine if that drug or those drugs will treat your medical condition before your plan will cover another drug for that condition."
    },
    {
      "Acronym": "B/D PA",
      "Expansion": "Part B vs. Part D",
      "Explanation": "This drug may be covered under either your Part D prescription drug benefits or as a Part B drug under your medical benefits, as determined by Medicare."
